# Проект FitLife - MVP версия 1.0WATER_PER_KG = 30ML_PER_L = 1000# 1. Знакомствоuser_name = input("Введите ваше имя: ")print(f"Здравствуйте, {user_name}!")user_age = int(input("Введите ваш возраст: "))# 2. Сбор данныхuser_weight = float(input("Введите ваш вес в кг (например, 70.45): "))user_height = float(input("Введите ваш рост в метрах (например, 1.75): "))# 3. Логика расчетов (Функции как "черный ящик": используем арифметику)# Формула ИМТ: вес разделить на (рост в квадрате)bmi = round(user_weight / (user_height**2), 1)# Подсчет воды: вес * 30 млwater_ml = user_weight * WATER_PER_KGwater_l = water_ml / ML_PER_Lwater_needed = round(water_l, 2)# 4. Вывод красивого результатаprint()print("=================================================")print()print(f"Отчет для пользователя: {user_name} ({user_age} г.)")print(f"Твой Индекс Массы Тела: {bmi}")print(f"Рекомендуемая норма воды: {water_needed} л. в день")print()print("=================================================")print()print("Расчет окончен. Будьте здоровы!")